function _handleWethRewardDistribution(
    Market.Data storage market,
    address assetOut,
    UD60x18 receivedWethX18
)
    internal
{
    // cache the total fee recipients shares as UD60x18
    UD60x18 feeRecipientsSharesX18 = ud60x18(MarketMakingEngineConfiguration.load().totalFeeRecipientsShares);

    // calculate the weth rewards for protocol and vaults
    UD60x18 receivedProtocolWethRewardX18 = receivedWethX18.mul(feeRecipientsSharesX18);
    UD60x18 receivedVaultsWethRewardX18 =
        receivedWethX18.mul(ud60x18(Constants.MAX_SHARES).sub(feeRecipientsSharesX18));

    // calculate leftover reward
    UD60x18 leftover = receivedWethX18.sub(receivedProtocolWethRewardX18).sub(receivedVaultsWethRewardX18);

    // add leftover reward to vault reward
    receivedVaultsWethRewardX18 = receivedVaultsWethRewardX18.add(leftover);

    // adds the weth received for protocol and vaults rewards using the assets previously paid by the engine
    // as fees, and remove its balance from the market's `receivedMarketFees` map
    market.receiveWethReward(assetOut, receivedProtocolWethRewardX18, receivedVaultsWethRewardX18);

    // recalculate markes' vaults credit delegations after receiving fees to push reward distribution
    Vault.recalculateVaultsCreditCapacity(market.getConnectedVaultsIds());
}

function stake(uint128 vaultId, uint128 shares) external {
    // to prevent safe cast overflow errors
    if (shares < Constants.MIN_OF_SHARES_TO_STAKE) {
        revert Errors.QuantityOfSharesLessThanTheMinimumAllowed(Constants.MIN_OF_SHARES_TO_STAKE, uint256(shares));
    }

    // fetch storage slot for vault by id
    Vault.Data storage vault = Vault.loadLive(vaultId);

    // prepare the `Vault::recalculateVaultsCreditCapacity` call
    uint256[] memory vaultsIds = new uint256[](1);
    vaultsIds[0] = uint256(vaultId);

    // updates the vault's credit capacity and perform all vault state
    // transitions before updating `msg.sender` staked shares
    Vault.recalculateVaultsCreditCapacity(vaultsIds);

    // load distribution data
    Distribution.Data storage wethRewardDistribution = vault.wethRewardDistribution;

    // cast actor address to bytes32
    bytes32 actorId = bytes32(uint256(uint160(msg.sender)));

    // accumulate the actor's pending reward before staking
    wethRewardDistribution.accumulateActor(actorId);

    // load actor distribution data
    Distribution.Actor storage actor = wethRewardDistribution.actor[actorId];

    // calculate actor updated shares amount
    UD60x18 updatedActorShares = ud60x18(actor.shares).add(ud60x18(shares));

    // update actor staked shares
    wethRewardDistribution.setActorShares(actorId, updatedActorShares);

    // transfer shares from actor
    IERC20(vault.indexToken).safeTransferFrom(msg.sender, address(this), shares);

    // emit an event
    emit LogStake(vaultId, msg.sender, shares);
}

function getCreditDepositsValueUsd(Data storage self) internal view returns (UD60x18 creditDepositsValueUsdX18) {
    // load the map of credit deposits and cache length
    EnumerableMap.AddressToUintMap storage creditDeposits = self.creditDeposits;
    uint256 creditDepositsLength = creditDeposits.length();

    for (uint256 i; i < creditDepositsLength; i++) {
        // load each credit deposit data & associated collateral
        (address asset, uint256 value) = creditDeposits.at(i);
        Collateral.Data storage collateral = Collateral.load(asset);

        // update the total credit deposits value
        creditDepositsValueUsdX18 =
            creditDepositsValueUsdX18.add((collateral.getAdjustedPrice().mul(ud60x18(value))));
    }
}

function getUnsettledRealizedDebt(Data storage self)
    internal
    view
    returns (SD59x18 unsettledRealizedDebtUsdX18)
{
    unsettledRealizedDebtUsdX18 =
        sd59x18(self.marketsRealizedDebtUsd).add(unary(ud60x18(self.depositedUsdc).intoSD59x18()));
}

function onERC721Received(address, address from, uint256 tokenId, bytes calldata data)
    external
    override
    returns (bytes4)
{
    // only Uniswap v3 NFTs allowed - sent from other contract
    if (msg.sender != address(nonfungiblePositionManager) || from == address(this)) {
        revert WrongContract();
    }

    (uint256 debtExchangeRateX96, uint256 lendExchangeRateX96) = _updateGlobalInterest();

    if (transformedTokenId == 0) {
        address owner = from;
        if (data.length > 0) {
            owner = abi.decode(data, (address));
        }
        loans[tokenId] = Loan(0);

        _addTokenToOwner(owner, tokenId);
        emit Add(tokenId, owner, 0);
    } else {
        uint256 oldTokenId = transformedTokenId;

        // if in transform mode - and a new position is sent - current position is replaced and returned
        if (tokenId != oldTokenId) {
            address owner = tokenOwner[oldTokenId];

            // set transformed token to new one
            transformedTokenId = tokenId;

            // copy debt to new token
            loans[tokenId] = Loan(loans[oldTokenId].debtShares);

            _addTokenToOwner(owner, tokenId);
            emit Add(tokenId, owner, oldTokenId);

            // clears data of old loan
            _cleanupLoan(oldTokenId, debtExchangeRateX96, lendExchangeRateX96, owner);

            // sets data of new loan
            _updateAndCheckCollateral(
                tokenId, debtExchangeRateX96, lendExchangeRateX96, 0, loans[tokenId].debtShares
            );
        }
    }

    return IERC721Receiver.onERC721Received.selector;
}

function execute(uint256 tokenId, Instructions memory instructions) public returns (uint256 newTokenId) {
    (,, address token0, address token1,,,, uint128 liquidity,,,,) = nonfungiblePositionManager.positions(tokenId);

    uint256 amount0;
    uint256 amount1;
    if (instructions.liquidity != 0) {
        (amount0, amount1) = _decreaseLiquidity(
            tokenId,
            instructions.liquidity,
            instructions.deadline,
            instructions.amountRemoveMin0,
            instructions.amountRemoveMin1
        );
    }
    (amount0, amount1) = _collectFees(
        tokenId,
        IERC20(token0),
        IERC20(token1),
        instructions.feeAmount0 == type(uint128).max
            ? type(uint128).max
            : (amount0 + instructions.feeAmount0).toUint128(),
        instructions.feeAmount1 == type(uint128).max
            ? type(uint128).max
            : (amount1 + instructions.feeAmount1).toUint128()
    );

    // check if enough tokens are available for swaps
    if (amount0 < instructions.amountIn0 || amount1 < instructions.amountIn1) {
        revert AmountError();
    }

    if (instructions.whatToDo == WhatToDo.COMPOUND_FEES) {
        if (instructions.targetToken == token0) {
            (liquidity, amount0, amount1) = _swapAndIncrease(
                SwapAndIncreaseLiquidityParams(
                    tokenId,
                    amount0,
                    amount1,
                    instructions.recipient,
                    instructions.deadline,
                    IERC20(token1),
                    instructions.amountIn1,
                    instructions.amountOut1Min,
                    instructions.swapData1,
                    0,
                    0,
                    "",
                    instructions.amountAddMin0,
                    instructions.amountAddMin1,
                    ""
                ),
                IERC20(token0),
                IERC20(token1),
                instructions.unwrap
            );
        } else if (instructions.targetToken == token1) {
            (liquidity, amount0, amount1) = _swapAndIncrease(
                SwapAndIncreaseLiquidityParams(
                    tokenId,
                    amount0,
                    amount1,
                    instructions.recipient,
                    instructions.deadline,
                    IERC20(token0),
                    0,
                    0,
                    "",
                    instructions.amountIn0,
                    instructions.amountOut0Min,
                    instructions.swapData0,
                    instructions.amountAddMin0,
                    instructions.amountAddMin1,
                    ""
                ),
                IERC20(token0),
                IERC20(token1),
                instructions.unwrap
            );
        } else {
            // no swap is done here
            (liquidity, amount0, amount1) = _swapAndIncrease(
                SwapAndIncreaseLiquidityParams(
                    tokenId,
                    amount0,
                    amount1,
                    instructions.recipient,
                    instructions.deadline,
                    IERC20(address(0)),
                    0,
                    0,
                    "",
                    0,
                    0,
                    "",
                    instructions.amountAddMin0,
                    instructions.amountAddMin1,
                    ""
                ),
                IERC20(token0),
                IERC20(token1),
                instructions.unwrap
            );
        }
        emit CompoundFees(tokenId, liquidity, amount0, amount1);
    } else if (instructions.whatToDo == WhatToDo.CHANGE_RANGE) {
        if (instructions.targetToken == token0) {
            (newTokenId,,,) = _swapAndMint(
                SwapAndMintParams(
                    IERC20(token0),
                    IERC20(token1),
                    instructions.fee,
                    instructions.tickLower,
                    instructions.tickUpper,
                    amount0,
                    amount1,
                    instructions.recipient,
                    instructions.recipientNFT,
                    instructions.deadline,
                    IERC20(token1),
                    instructions.amountIn1,
                    instructions.amountOut1Min,
                    instructions.swapData1,
                    0,
                    0,
                    "",
                    instructions.amountAddMin0,
                    instructions.amountAddMin1,
                    instructions.swapAndMintReturnData,
                    ""
                ),
                instructions.unwrap
            );
        } else if (instructions.targetToken == token1) {
            (newTokenId,,,) = _swapAndMint(
                SwapAndMintParams(
                    IERC20(token0),
                    IERC20(token1),
                    instructions.fee,
                    instructions.tickLower,
                    instructions.tickUpper,
                    amount0,
                    amount1,
                    instructions.recipient,
                    instructions.recipientNFT,
                    instructions.deadline,
                    IERC20(token0),
                    0,
                    0,
                    "",
                    instructions.amountIn0,
                    instructions.amountOut0Min,
                    instructions.swapData0,
                    instructions.amountAddMin0,
                    instructions.amountAddMin1,
                    instructions.swapAndMintReturnData,
                    ""
                ),
                instructions.unwrap
            );
        } else {
            // no swap is done here
            (newTokenId,,,) = _swapAndMint(
                SwapAndMintParams(
                    IERC20(token0),
                    IERC20(token1),
                    instructions.fee,
                    instructions.tickLower,
                    instructions.tickUpper,
                    amount0,
                    amount1,
                    instructions.recipient,
                    instructions.recipientNFT,
                    instructions.deadline,
                    IERC20(address(0)),
                    0,
                    0,
                    "",
                    0,
                    0,
                    "",
                    instructions.amountAddMin0,
                    instructions.amountAddMin1,
                    instructions.swapAndMintReturnData,
                    ""
                ),
                instructions.unwrap
            );
        }
        emit ChangeRange(tokenId, newTokenId);
    } else if (instructions.whatToDo == WhatToDo.WITHDRAW_AND_COLLECT_AND_SWAP) {
        uint256 targetAmount;
        if (token0 != instructions.targetToken) {
            (uint256 amountInDelta, uint256 amountOutDelta) = _routerSwap(
                Swapper.RouterSwapParams(
                    IERC20(token0),
                    IERC20(instructions.targetToken),
                    amount0,
                    instructions.amountOut0Min,
                    instructions.swapData0
                )
            );
            if (amountInDelta < amount0) {
                _transferToken(instructions.recipient, IERC20(token0), amount0 - amountInDelta, instructions.unwrap);
            }
            targetAmount += amountOutDelta;
        } else {
            targetAmount += amount0;
        }
        if (token1 != instructions.targetToken) {
            (uint256 amountInDelta, uint256 amountOutDelta) = _routerSwap(
                Swapper.RouterSwapParams(
                    IERC20(token1),
                    IERC20(instructions.targetToken),
                    amount1,
                    instructions.amountOut1Min,
                    instructions.swapData1
                )
            );
            if (amountInDelta < amount1) {
                _transferToken(instructions.recipient, IERC20(token1), amount1 - amountInDelta, instructions.unwrap);
            }
            targetAmount += amountOutDelta;
        } else {
            targetAmount += amount1;
        }

        // send complete target amount
        if (targetAmount != 0 && instructions.targetToken != address(0)) {
            _transferToken(
                instructions.recipient, IERC20(instructions.targetToken), targetAmount, instructions.unwrap
            );
        }

        emit WithdrawAndCollectAndSwap(tokenId, instructions.targetToken, targetAmount);
    } else {
        revert NotSupportedWhatToDo();
    }
}

function _getReferencePoolPriceX96(IUniswapV3Pool pool, uint32 twapSeconds) internal view returns (uint256) {
    uint160 sqrtPriceX96;
    // if twap seconds set to 0 just use pool price
    if (twapSeconds == 0) {
        (sqrtPriceX96,,,,,,) = pool.slot0();
    } else {
        uint32[] memory secondsAgos = new uint32[](2);
        secondsAgos[0] = 0; // from (before)
        secondsAgos[1] = twapSeconds; // from (before)
        (int56[] memory tickCumulatives,) = pool.observe(secondsAgos); // pool observe may fail when there is not enough history available (only use pool with enough history!)
        int24 tick = int24((tickCumulatives[0] - tickCumulatives[1]) / int56(uint56(twapSeconds)));
        sqrtPriceX96 = TickMath.getSqrtRatioAtTick(tick);
    }

    return FullMath.mulDiv(sqrtPriceX96, sqrtPriceX96, Q96);
}

function _cleanupLoan(uint256 tokenId, uint256 debtExchangeRateX96, uint256 lendExchangeRateX96, address owner)
    internal
{
    _removeTokenFromOwner(owner, tokenId);
    _updateAndCheckCollateral(tokenId, debtExchangeRateX96, lendExchangeRateX96, loans[tokenId].debtShares, 0);
    delete loans[tokenId];
    nonfungiblePositionManager.safeTransferFrom(address(this), owner, tokenId);
    emit Remove(tokenId, owner);
}

function settleLiquidation(
    address liquidator,
    address liquidatee,
    int256 bonus
) external payable onlyPanopticPool {
    if (bonus < 0) {
        uint256 bonusAbs;

        unchecked {
            bonusAbs = uint256(-bonus);
        }
        address _poolManager = address(poolManager());

        if (_poolManager == address(0)) {
            uint256 underlyingTokenBalance = ERC20Minimal(underlyingToken()).balanceOf(
                liquidator
            );
            if (underlyingTokenBalance < bonusAbs)
                revert Errors.NotEnoughTokens(
                    underlyingToken(),
                    bonusAbs,
                    underlyingTokenBalance
                );
            SafeTransferLib.safeTransferFrom(
                underlyingToken(),
                liquidator,
                msg.sender,
                bonusAbs
            );
        }
        _mint(liquidatee, convertToShares(bonusAbs));

        s_depositedAssets += uint128(bonusAbs);

        uint256 liquidateeBalance = balanceOf[liquidatee];

        if (type(uint248).max > liquidateeBalance) {
            balanceOf[liquidatee] = 0;
            // keep checked to catch under/overflows
            _internalSupply += type(uint248).max - liquidateeBalance;
        } else {
            // keep checked to catch under/overflows
            balanceOf[liquidatee] = liquidateeBalance - type(uint248).max;
        }
        if (_poolManager != address(0)) {
            _settleCurrencyDelta(liquidator, int256(bonusAbs));
        }
    } else {
        uint256 liquidateeBalance = balanceOf[liquidatee];

        if (type(uint248).max > liquidateeBalance) {
            // keep checked to catch under/overflows
            _internalSupply += type(uint248).max - liquidateeBalance;
            liquidateeBalance = 0;
        } else {
            // keep checked to catch under/overflows
            liquidateeBalance -= type(uint248).max;
        }
        balanceOf[liquidatee] = liquidateeBalance;

        uint256 bonusShares = convertToShares(uint256(bonus));

        // if requested amount is larger than user balance, transfer their balance and mint the remaining shares
        if (bonusShares > liquidateeBalance) {
            _transferFrom(liquidatee, liquidator, liquidateeBalance);

            // this is paying out protocol loss, so correct for that in the amount of shares to be minted
            // X: total assets in vault
            // Y: total supply of shares
            // Z: desired value (assets) of shares to be minted
            // N: total shares corresponding to Z
            // T: transferred shares from liquidatee which are a component of N but do not contribute toward protocol loss
            // Z = N * X / (Y + N - T)
            // Z * (Y + N - T) = N * X
            // ZY + ZN - ZT = NX
            // ZY - ZT = N(X - Z)
            // N = (ZY - ZT) / (X - Z)
            // N = Z(Y - T) / (X - Z)
            // subtract delegatee balance from N since it was already transferred to the delegator
            uint256 _totalSupply = totalSupply();

            // keep checked to catch any casting/math errors
            _mint(
                liquidator,
                Math.min(
                    Math.mulDivCapped(
                        uint256(bonus),
                        _totalSupply - liquidateeBalance,
                        uint256(Math.max(1, int256(totalAssets()) - bonus))
                    ) - liquidateeBalance,
                    _totalSupply * DECIMALS
                )
            );
        } else {
            _transferFrom(liquidatee, liquidator, bonusShares);
        }

        // refund liquidator if they attached value expecting to settle a negative bonus in the native currency
        if (msg.value > 0) SafeTransferLib.safeTransferETH(liquidator, msg.value);
    }
}

function settleBurn(
    address optionOwner,
    int128 longAmount,
    int128 shortAmount,
    int128 ammDeltaAmount,
    int128 realizedPremium,
    RiskParameters riskParameters
) external onlyPanopticPool returns (int128) {
    (, int128 tokenPaid, uint256 _totalAssets, uint256 _totalSupply) = _updateBalancesAndSettle(
        optionOwner,
        false, // isCreation = false
        longAmount,
        shortAmount,
        ammDeltaAmount,
        realizedPremium
    );

    if (realizedPremium != 0) {
        uint128 commissionFee;
        // compute the minimum of the notionalFee and the premiumFee
        {
            uint128 commissionP;
            unchecked {
                commissionP = realizedPremium > 0
                    ? uint128(realizedPremium)
                    : uint128(-realizedPremium);
            }
            uint128 commissionFeeP = Math
                .mulDivRoundingUp(commissionP, riskParameters.premiumFee(), DECIMALS)
                .toUint128();
            uint128 commissionN = uint256(int256(shortAmount) + int256(longAmount)).toUint128();
            uint128 commissionFeeN;
            unchecked {
                commissionFeeN = Math
                    .mulDivRoundingUp(commissionN, 10 * riskParameters.notionalFee(), DECIMALS)
                    .toUint128();
            }
            commissionFee = Math.min(commissionFeeP, commissionFeeN).toUint128();
        }

        uint256 sharesToBurn = Math.mulDivRoundingUp(commissionFee, _totalSupply, _totalAssets);

        if (riskParameters.feeRecipient() == 0) {
            _burn(optionOwner, sharesToBurn);
            emit CommissionPaid(optionOwner, address(0), commissionFee, 0);
        } else {
            unchecked {
                _transferFrom(
                    optionOwner,
                    address(riskEngine()),
                    (sharesToBurn * riskParameters.protocolSplit()) / DECIMALS
                );
                _transferFrom(
                    optionOwner,
                    address(uint160(riskParameters.feeRecipient())),
                    (sharesToBurn * riskParameters.builderSplit()) / DECIMALS
                );
                emit CommissionPaid(
                    optionOwner,
                    address(uint160(riskParameters.feeRecipient())),
                    uint128((commissionFee * riskParameters.protocolSplit()) / DECIMALS),
                    uint128((commissionFee * riskParameters.protocolSplit()) / DECIMALS)
                );
            }
        }
    }

    return tokenPaid;
}

function _getRequiredCollateralAtTickSinglePosition(
    TokenId tokenId,
    uint128 positionSize,
    int24 atTick,
    int16 poolUtilization,
    bool underlyingIsToken0
) internal view returns (uint256 tokenRequired, uint256 credits) {
    uint256 numLegs = tokenId.countLegs();

    unchecked {
        for (uint256 index = 0; index < numLegs; ++index) {
            // bypass the collateral calculation if tokenType doesn't match the requested token (underlyingIsToken0)
            if (tokenId.tokenType(index) != (underlyingIsToken0 ? 0 : 1)) continue;

            if (tokenId.width(index) == 0 && tokenId.isLong(index) == 1) {
                LeftRightUnsigned amountsMoved = PanopticMath.getAmountsMoved(
                    tokenId,
                    positionSize,
                    index,
                    false
                );
                credits = tokenId.tokenType(index) == 0
                    ? amountsMoved.rightSlot()
                    : amountsMoved.leftSlot();
            }
            // Increment the tokenRequired accumulator
            tokenRequired += _getRequiredCollateralSingleLeg(
                tokenId,
                index,
                positionSize,
                atTick,
                poolUtilization
            );
        }
    }
}

function twapEMA(OraclePack oraclePack) external pure returns (int24) {
    // Extract current EMAs from oraclePack
    (int256 eonsEMA, int256 slowEMA, int256 fastEMA, , ) = oraclePack.getEMAs();
    return int24((6 * fastEMA + 3 * slowEMA + eonsEMA) / 10);
}

function withdrawTokens(
    uint256[] calldata request
)
    external
    payable
    returns (address)
{
    if (!_enabled) {
        revert BridgeNotEnabledError();
    }

    // Header is always the first uint256 of the serialized request.
    uint256 header = request[0];

    // Any error or permission fail in the message consumption will cause a revert.
    // After message being consumed, it is considered legit and tokens can be withdrawn.
    if (Protocol.canUseWithdrawAuto(header)) {
        // 2024-03-19: disabled autoWithdraw after audit report
        // _consumeMessageAutoWithdraw(_starklaneL2Address, request);
        revert NotSupportedYetError();
    } else {
        _consumeMessageStarknet(_starknetCoreAddress, _starklaneL2Address, request);
    }

    Request memory req = Protocol.requestDeserialize(request, 0);

    address collectionL1 = _verifyRequestAddresses(req.collectionL1, req.collectionL2);

    CollectionType ctype = Protocol.collectionTypeFromHeader(header);

    if (collectionL1 == address(0x0)) {
        if (ctype == CollectionType.ERC721) {
            collectionL1 = _deployERC721Bridgeable(
                req.name,
                req.symbol,
                req.collectionL2,
                req.hash
            );
            // update whitelist if needed
            _whiteListCollection(collectionL1, true);
        } else {
            revert NotSupportedYetError();
        }
    }

    for (uint256 i = 0; i < req.tokenIds.length; i++) {
        uint256 id = req.tokenIds[i];

        bool wasEscrowed = _withdrawFromEscrow(ctype, collectionL1, req.ownerL1, id);

        if (!wasEscrowed) {
            // TODO: perhaps, implement the same interface for ERC721 and ERC1155
            // As we only want to deal with ERC1155 token with value = 1.
            // Also, check what to do with URIs. If the URI storage is supported
            // or not for ERC721. If supported, we may need to mint with an URI.
            IERC721Bridgeable(collectionL1).mintFromBridge(req.ownerL1, id);
        }
    }

    emit WithdrawRequestCompleted(req.hash, block.timestamp, request);

    return collectionL1;
}
